-- An incremental model: built in full the first time, then only rows past the watermark.
CREATE TABLE IF NOT EXISTS marts.fct_order_fulfilment AS
-- An accumulating snapshot: one row per order_id, line_number, updated as it passes each
-- milestone (ordered_on, shipped_on, received_on). A milestone once reached keeps its date, even when
-- a later run does not see it again.

with lineitem as (

    select * from staging.stg_tpch_erp__lineitem

),

orders as (

    select * from staging.stg_tpch_erp__orders

),

incoming as (

    select
        cast(lineitem.l_orderkey as BIGINT) as order_id,
        cast(lineitem.l_linenumber as INTEGER) as line_number,
        coalesce(cast(orders.o_custkey as BIGINT), cast(-1 as BIGINT)) as customer_id,
        cast(orders.o_orderdate as DATE) as ordered_on,
        cast(lineitem.l_commitdate as DATE) as committed_on,
        cast(lineitem.l_shipdate as DATE) as shipped_on,
        cast(lineitem.l_receiptdate as DATE) as received_on,
        cast(current_timestamp as TIMESTAMPTZ) as _updated_at,
        cast(lineitem._ingested_at as TIMESTAMPTZ) as _loaded_at
    from lineitem
    left join orders
        on lineitem.l_orderkey = orders.o_orderkey

),

merged as (

    select
        incoming.order_id,
        incoming.line_number,
        incoming.customer_id,

        incoming.ordered_on,

        incoming.committed_on,

        incoming.shipped_on,

        incoming.received_on,

        incoming._updated_at,
        incoming._loaded_at
    from incoming

)

select
    merged.order_id,
    merged.line_number,
    merged.customer_id,
    merged.ordered_on,
    merged.committed_on,
    merged.shipped_on,
    merged.received_on,
    merged._updated_at,
    merged._loaded_at,
    DATE_DIFF('DAY', merged.ordered_on, merged.shipped_on) as ordered_on_to_shipped_on_days,
    DATE_DIFF('DAY', merged.shipped_on, merged.received_on) as shipped_on_to_received_on_days,
    case when merged.received_on is not null then 'received_on' when merged.shipped_on is not null then 'shipped_on' when merged.ordered_on is not null then 'ordered_on' end as current_milestone
from merged;
-- The rows past the watermark, kept aside while the old versions of them are removed.
