        coalesce(incoming.received_on, reached.received_on) as received_on,

        incoming._updated_at,
        incoming._loaded_at
    from incoming

    left join marts.fct_order_fulfilment as reached
        on reached.order_id = incoming.order_id and reached.line_number = incoming.line_number

)

